package chess

// weakTable is pgn-extract's HashTab (map.c init_hashtab): one 64-bit value
// per (file, rank, piece type, colour), generated by a fixed linear
// congruential sequence so that every run of either tool produces the
// same values. Indexed [file][rank][PieceType-1][colour], colour 0 for
// Black and 1 for White, in the C tool's loop order.
var weakTable [8][8][6][2]uint64

func init() {
	var seed uint64
	for file := 0; file < 8; file++ {
		for rank := 0; rank < 8; rank++ {
			for piece := 0; piece < 6; piece++ {
				for colour := 0; colour < 2; colour++ {
					seed = seed*1103515245 + 123456789
					weakTable[file][rank][piece][colour] = seed >> 7
				}
			}
		}
	}
}

// WeakHash computes pgn-extract's weak_hash_value for the position: the
// XOR of a fixed per-(square, piece, colour) table over every occupied
// square, with no side-to-move, castling or en passant contribution. It is
// the value behind the C tool's HashCode tag (the sum of the weak hashes
// of every main-line position after a move) and its duplicate detection.
// PlacementKey is pgnx's own placement hash; the two agree only on
// equality, never in value.
func (b *Board) WeakHash() uint64 {
	var h uint64
	for file := 0; file < 8; file++ {
		for rank := 0; rank < 8; rank++ {
			p := b.squares[file][rank]
			if p.Type == NoPiece {
				continue
			}
			colour := 0
			if p.Color == White {
				colour = 1
			}
			h ^= weakTable[file][rank][p.Type-1][colour]
		}
	}
	return h
}
